'use strict';
// C1, the session transport's wire layer (docs/superpowers/specs/
// 2026-11-15-shared-runtime-design.md section 1, contract 2), server free:
// frames, the M payload, the handshake MACs, the secret file's form, and
// the line rules the runtime applies whatever the shim did. Each case runs
// the conformance vectors the Rust shim also runs, read from the spec's own
// file (docs/superpowers/specs/shared-runtime-wire/vectors.json, generated by
// make-vectors.js), never a copy that could fall behind it.
const assert = require('assert');
const frames = require('../../lib/session-transport/frames');
const handshake = require('../../lib/session-transport/handshake');
const lines = require('../../lib/session-transport/lines');
const V = require('../../docs/superpowers/specs/shared-runtime-wire/vectors.json');

const hexOf = (b) => Buffer.from(b).toString('hex');
const fromHex = (h) => Buffer.from(h, 'hex');

describe('sessions 01: the wire (contract 2)', () => {
  // the generator is the source of vectors.json: run as it is, it writes the
  // file byte for byte, so a hand edit to either alone fails here (#438's
  // high review). Run on a copy in a directory of its own: it writes beside
  // itself.
  it('make-vectors.js writes vectors.json byte for byte', function() {
    this.timeout(30000);
    const fs = require('fs');
    const os = require('os');
    const path = require('path');
    const here = path.join(__dirname, '..', '..', 'docs', 'superpowers', 'specs', 'shared-runtime-wire');
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ch-make-vectors-'));
    try {
      fs.copyFileSync(path.join(here, 'make-vectors.js'), path.join(dir, 'make-vectors.js'));
      const run = require('child_process').spawnSync(process.execPath, [path.join(dir, 'make-vectors.js')], {encoding: 'utf8', timeout: 25000});
      assert.strictEqual(run.status, 0, run.stderr);
      assert.ok(fs.readFileSync(path.join(dir, 'vectors.json')).equals(fs.readFileSync(path.join(here, 'vectors.json'))),
        'make-vectors.js and vectors.json disagree: edit the generator, run it, and commit both');
    } finally {
      fs.rmSync(dir, {recursive: true, force: true});
    }
  });

  // (the shim's answer to a session refused because it lost one of its
  // tightenings: words of its own, not SESSION_CANT_FALL_BACK's, which say
  // the shared runtime failed; business's words, 11-28)
  it('the answer to a session that lost its tightenings is in these words, exact apart from the id', () => {
    const v = V.sessionTighteningsLostAnswer;
    assert.ok(v != null, 'the vector is there');
    assert.strictEqual(v.json, '{"jsonrpc":"2.0","id":7,"error":{"code":-32603,"message":"countinghouse couldn\'t keep the settings this session tightened, so the session stops: restart it","data":{"countinghouse/code":"SESSION_TIGHTENINGS_LOST","retryable":false}}}');
    assert.strictEqual(JSON.parse(v.json).error.data['countinghouse/code'], 'SESSION_TIGHTENINGS_LOST');
    assert.strictEqual(v.stderr, 'ch-shim: the runtime couldn\'t resume this session, and a setting this session tightened couldn\'t be kept, so the session stops: restart it');
    // (SESSION_CANT_FALL_BACK stays for a mid-session failure and a session
    // that can't share)
    assert.match(V.sessionCantFallBackAnswer.json, /SESSION_CANT_FALL_BACK/);
  });

  it('runs vectors of the contract this code speaks', () => {
    assert.strictEqual(V.contract, frames.CONTRACT);
  });

  describe('frames', () => {
    it('encodes every handshake and control vector byte for byte', () => {
      const kinds = {hello: 'H', prove: 'P', auth: 'A', authResume: 'A', welcome: 'W', refused: 'R'};
      for (const [name, kind] of Object.entries(kinds)) {
        assert.strictEqual(hexOf(frames.encode(kind, V.handshake.frames[name].json)), V.handshake.frames[name].hex, name);
      }
      for (const [name, c] of Object.entries(V.control)) assert.strictEqual(hexOf(frames.encode('C', c.json)), c.hex, name);
    });

    it('decodes frames split at every byte, in order', () => {
      const all = Buffer.concat([fromHex(V.handshake.frames.hello.hex), fromHex(V.control.drain.hex), fromHex(V.messages.requestToRuntime.hex)]);
      for (let cut = 1; cut < all.length; cut++) {
        const got = [];
        const d = frames.createDecoder({caps: {M: 1 << 20}, onFrame: (kind, payload) => got.push([kind, payload]), onError: (why) => assert.fail(why)});
        d.push(all.subarray(0, cut));
        d.push(all.subarray(cut));
        assert.deepStrictEqual(got.map(([k]) => k), ['H', 'C', 'M'], `cut at ${cut}`);
        assert.strictEqual(got[0][1].toString('utf8'), V.handshake.frames.hello.json);
      }
    });

    it('refuses an over-cap length before reading its payload, and an unknown kind', () => {
      const errors = [];
      const d = frames.createDecoder({caps: {M: 16}, onFrame: () => assert.fail('no frame'), onError: (why) => errors.push(why)});
      const head = Buffer.alloc(5);
      head.write('M', 0, 'ascii');
      head.writeUInt32BE(17, 1);
      d.push(head);
      assert.strictEqual(errors.length, 1, 'refused from the head alone');
      const errs2 = [];
      const d2 = frames.createDecoder({caps: {M: 16}, onFrame: () => assert.fail('no frame'), onError: (why) => errs2.push(why)});
      d2.push(Buffer.from([0x5a, 0, 0, 0, 0]));
      assert.strictEqual(errs2.length, 1, 'kind Z');
    });

    it('caps HELLO at 507 bytes, the other handshake frames at 4096 and C at 65536', () => {
      assert.strictEqual(frames.CAPS.H, 507);
      for (const k of ['P', 'A', 'W', 'R']) assert.strictEqual(frames.CAPS[k], 4096);
      assert.strictEqual(frames.CAPS.C, 65536);
    });
  });

  describe('M payloads', () => {
    it('encodes and decodes the message vectors', () => {
      for (const name of ['requestToRuntime', 'oddIdToRuntime', 'batchToRuntime', 'clientResponseToRuntime', 'nonStringMethod', 'escapedIdKey',
        'loneSurrogateKey', 'notificationToRuntime', 'replyToShim', 'unmatchedReplyToShim', 'notificationToShim']) {
        const m = V.messages[name];
        assert.strictEqual(hexOf(frames.encode('M', frames.encodeM(m.header, Buffer.from(m.line, 'utf8')))), m.hex, name);
        const payload = fromHex(m.hex).subarray(5);
        const back = frames.decodeM(payload);
        assert.deepStrictEqual(back.header, m.header, name);
        assert.strictEqual(back.line.toString('utf8'), m.line, name);
      }
    });

    it('refuses each malformed payload', () => {
      for (const name of ['payloadUnder2Bytes', 'headerLongerThanPayload', 'headerNotAnObject', 'seqNotAnInteger']) {
        const payload = fromHex(V.messages.malformed[name]).subarray(5);
        assert.throws(() => frames.decodeM(payload), /M/, name);
      }
    });
  });

  describe('the handshake', () => {
    const secret = fromHex(V.handshake.secretHex);
    const nc = fromHex(V.handshake.ncHex);
    const ns = fromHex(V.handshake.nsHex);

    it('makes ms and mc as the vectors have them, with the protocol inside both', () => {
      assert.strictEqual(hexOf(handshake.serverMac(secret, 1, nc, ns)), V.handshake.msHex);
      assert.strictEqual(hexOf(handshake.clientMac(secret, 1, ns, nc)), V.handshake.mcHex);
      assert.notStrictEqual(hexOf(handshake.serverMac(secret, 2, nc, ns)), V.handshake.msHex);
    });

    it('checks a MAC in constant time, refusing a one-bit change and a wrong length', () => {
      const ms = fromHex(V.handshake.msHex);
      assert.strictEqual(handshake.macEquals(ms, Buffer.from(ms)), true);
      const flipped = Buffer.from(ms);
      flipped[0] ^= 0x01;
      assert.strictEqual(handshake.macEquals(ms, flipped), false);
      assert.strictEqual(handshake.macEquals(ms, ms.subarray(1)), false);
    });

    it('the conditions why vectors are consistent: each accepted one passes the rule, each refused one fails it', () => {
      const W = V.conditionsWhy;
      const hidden = new RegExp(`[${W.hiddenClass}]`, 'u');
      const ok = (w) => w != null && typeof(w) === 'object' && !Array.isArray(w) && W.reasons.includes(w.reason)
        && Object.keys(w).every((k) => k === 'reason' || k === 'at')
        && (w.at === undefined || (typeof(w.at) === 'string' && w.at.startsWith('~/') && Array.from(w.at).length <= 200 && !hidden.test(w.at)
          && !w.at.includes('\\') && w.at.slice(2).split('/').every((seg) => seg !== '' && seg !== '..')));
      for (const {why, value} of W.accepted) assert.strictEqual(ok(value), true, why);
      for (const {why, value} of W.refused) assert.strictEqual(ok(value), false, why);
    });

    it('the GitHub token order\'s vectors follow their rule: start, the daemon and the conditions check agree, and the outcome follows from them', () => {
      for (const c of V.githubTokenPrecedence.cases) {
        const {env, stored, ghLogin, daemonHolds} = c.input;
        const storedOk = stored === true;
        const start = env.includes('COUNTINGHOUSE_GITHUB_TOKEN') ? 'environment' : storedOk ? 'stored' : ghLogin ? 'gh' : env.includes('GITHUB_TOKEN') ? 'GITHUB_TOKEN' : null;
        const daemon = storedOk ? 'stored' : ghLogin ? 'gh' : null;
        const conditions = start === 'environment' ? 'mac(env)' : start === 'stored' ? 'mac(stored)' : start === 'GITHUB_TOKEN' ? 'mac(GITHUB_TOKEN)' : null;
        // null is "the daemon's", whatever it holds (listener.js); a hash
        // shares only when it is the daemon's own token's
        const shares = conditions === null || (conditions === 'mac(stored)' && daemonHolds === 'stored');
        assert.deepStrictEqual([c.start, c.daemon, c.conditions, c.outcome], [start, daemon, conditions, shares ? 'shares' : 'own-runtime (token)'], c.why);
      }
    });

    // M6 (#413 rev 3 section 16, rule 7): the pack form is gone; a message
    // in it is refused on any runtime, before anything is read
    it('the pack form is gone: a pack-form load, reload or unload is refused, shared or not', async () => {
      for (const shared of [true, false]) {
        const control = require('../../lib/module-control').createModuleControl({
          shared: () => shared, mm: {}, dm: {}, toolsOf: async () => [],
          packs: {loadPack: async () => assert.fail('loaded'), reloadPack: async () => assert.fail('reloaded'), unloadPack: async () => assert.fail('unloaded')},
          notices: {add: () => {}}});
        const scenario = '/home/example/.countinghouse/packs/example/node_modules/@countinghouse/ch-pack-example';
        for (const m of [{type: 'load', name: '@countinghouse/ch-pack-example', scenario, pack: 'example', global: true},
          {type: 'reload', name: '@countinghouse/ch-pack-example', scenario, pack: 'example'},
          {type: 'unload', name: '@countinghouse/ch-pack-example', pack: 'example'}]) {
          await assert.rejects(control[m.type](m), (e) => e.code === 'CONTROL_FAILED', `${m.type}, shared ${shared}`);
        }
      }
    });

    // M4 (#413 section 7.5): the module form, read by the runtime's own
    // structural check (lib/modules-in-place.js moduleMessageProblem) before
    // anything is read from disk
    it('the module messages\' vectors: the runtime takes every accepted one and refuses each refused one for its reason', () => {
      const M = V.moduleMessages;
      const {moduleMessageProblem} = require('../../lib/modules-in-place');
      const {SLOT, isPackage} = require('../../lib/remote/credentials');
      assert.strictEqual(M.slotPattern, SLOT.source);
      const pkg = new RegExp(M.packagePattern);
      for (const {why, message} of M.accepted) {
        assert.strictEqual(moduleMessageProblem(message.type, message), null, why);
        for (const n of [].concat(message.name || [], message.names || [], Object.keys(message.dirs || {}))) assert.ok(pkg.test(n) && isPackage(n), `${why}: ${n}`);
      }
      for (const {why, reason, message} of M.refused) {
        const p = moduleMessageProblem(message.type, message);
        assert.ok(p != null, why);
        assert.strictEqual(p.reason, reason, `${why}: ${p.message}`);
      }
      assert.deepStrictEqual([...new Set(M.refused.map((r) => r.reason))].sort(), ['credentials', 'dirs', 'name', 'names', 'old-field']);
    });

    it('makes the token MAC as the vectors have it', () => {
      assert.strictEqual(handshake.tokenMac(secret, V.tokenMac.token).toString('base64'), V.tokenMac.macB64);
    });

    it('makes a pack credential\'s MAC as the vectors have it', () => {
      assert.strictEqual(handshake.credentialMac(secret, V.credentialMac.name, V.credentialMac.value).toString('base64'), V.credentialMac.macB64);
      assert.deepStrictEqual(JSON.parse(V.control.clientCredentials.json).credentials, {[V.credentialMac.name]: V.credentialMac.macB64});
    });

    it('reads the accepted secret files and refuses the others', () => {
      for (const s of V.secretFiles.accepted) assert.strictEqual(hexOf(handshake.parseSecret(s)), V.handshake.secretHex, JSON.stringify(s));
      for (const s of V.secretFiles.refused) assert.strictEqual(handshake.parseSecret(s), null, JSON.stringify(s));
      assert.strictEqual(handshake.formatSecret(secret), V.secretFile.contents);
    });
  });

  describe('the runtime\'s line rules', () => {
    const lineOf = (name) => (V.messages[name].lineHex != null ? fromHex(V.messages[name].lineHex) : Buffer.from(V.messages[name].line, 'utf8'));

    it('dispatches a line that came with a seq', () => {
      const r = lines.classify(lineOf('requestToRuntime'), {seq: 1});
      assert.strictEqual(r.dispatch, true);
      assert.strictEqual(r.message.id, 7);
    });

    it('never dispatches a line with an id that came without a seq, and answers -32600 with its id', () => {
      const r = lines.classify(lineOf('loneSurrogateKey'), null);
      assert.strictEqual(r.dispatch, false);
      assert.strictEqual(JSON.stringify(r.answer), V.messages.loneSurrogateKey.runtimeAnswer);
      const escaped = lines.classify(lineOf('escapedIdKey'), null);
      assert.strictEqual(escaped.dispatch, false, 'i\\u0064 is id');
    });

    it('decodes UTF-8 fatally: invalid UTF-8 is a parse error and nothing runs', () => {
      const r = lines.classify(lineOf('invalidUtf8'), null);
      assert.strictEqual(r.dispatch, false);
      assert.strictEqual(JSON.stringify(r.answer), V.messages.invalidUtf8.runtimeAnswer);
    });

    it('dispatches a notification without a seq, and ignores a response', () => {
      assert.strictEqual(lines.classify(lineOf('notificationToRuntime'), null).dispatch, true);
      const resp = lines.classify(lineOf('clientResponseToRuntime'), null);
      assert.strictEqual(resp.dispatch, false);
      assert.strictEqual(resp.answer, null);
    });

    it('a batch without a seq is never dispatched', () => {
      const r = lines.classify(lineOf('batchToRuntime'), null);
      assert.strictEqual(r.dispatch, false);
    });
  });
});
